module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    input  logic done_counting,
    input  logic ack,
    output logic shift_ena,
    output logic counting,
    output logic done
);

  typedef enum logic [1:0] {
    S_SEARCH = 2'b00,
    S_SHIFT  = 2'b01,
    S_COUNT  = 2'b10,
    S_DONE   = 2'b11
  } state_t;

  state_t state, next_state;
  logic [3:0] sr;
  logic [3:0] next_sr;
  logic [1:0] count;

  // Combinational next shift register value
  assign next_sr = {sr[2:0], data};

  // Shift register for pattern detection
  always_ff @(posedge clk) begin
    if (reset) begin
      sr <= 4'b0;
    end else if (state == S_SEARCH) begin
      sr <= next_sr;
    end
  end

  // 2-bit counter for 4 shift cycles
  always_ff @(posedge clk) begin
    if (reset) begin
      count <= 2'b0;
    end else if (state == S_SHIFT) begin
      count <= count + 1'b1;
    end else begin
      count <= 2'b0;
    end
  end

  // State register
  always_ff @(posedge clk) begin
    if (reset) begin
      state <= S_SEARCH;
    end else begin
      state <= next_state;
    end
  end

  // Next state logic
  always_comb begin
    next_state = state;
    case (state)
      S_SEARCH: begin
        if (next_sr == 4'b1101) begin
          next_state = S_SHIFT;
        end
      end
      S_SHIFT: begin
        if (count == 2'b11) begin
          next_state = S_COUNT;
        end
      end
      S_COUNT: begin
        if (done_counting) begin
          next_state = S_DONE;
        end
      end
      S_DONE: begin
        if (ack) begin
          next_state = S_SEARCH;
        end
      end
      default: next_state = S_SEARCH;
    endcase
  end

  // Output logic
  assign shift_ena = (state == S_SHIFT);
  assign counting  = (state == S_COUNT);
  assign done      = (state == S_DONE);

endmodule

