module tb_TopModule;
  logic clk;
  logic reset;
  logic data;
  logic done_counting;
  logic ack;
  logic shift_ena;
  logic counting;
  logic done;

  TopModule dut (
    .clk(clk),
    .reset(reset),
    .data(data),
    .done_counting(done_counting),
    .ack(ack),
    .shift_ena(shift_ena),
    .counting(counting),
    .done(done)
  );

  // Clock generation: 10ns period
  always #5 clk = ~clk;

  initial begin
    clk = 0;
    reset = 1;
    data = 0;
    done_counting = 0;
    ack = 0;

    #12;
    reset = 0;
    #10;

    // Send pattern 1101
    // Bit 1
    data = 1; #10;
    // Bit 1
    data = 1; #10;
    // Bit 0
    data = 0; #10;
    // Bit 1 -> 1101 detected here
    data = 1; 

    // Check that shift_ena asserts for 4 cycles starting next cycle
    #2; // check immediately after clock edge
    if (shift_ena !== 0) begin
      $display("FAIL: shift_ena asserted too early");
      $display("SELFTEST FAIL: shift_ena timing");
      $finish;
    end

    #8; // 1st cycle of shift_ena
    if (shift_ena !== 1) begin
      $display("FAIL: shift_ena not high on cycle 1");
      $display("SELFTEST FAIL: shift_ena count 1");
      $finish;
    end

    #10; // 2nd cycle
    if (shift_ena !== 1) begin
      $display("FAIL: shift_ena not high on cycle 2");
      $finish;
    end

    #10; // 3rd cycle
    if (shift_ena !== 1) begin
      $display("FAIL: shift_ena not high on cycle 3");
      $finish;
    end

    #10; // 4th cycle
    if (shift_ena !== 1) begin
      $display("FAIL: shift_ena not high on cycle 4");
      $finish;
    end

    #10; // Should transition to counting
    if (counting !== 1) begin
      $display("FAIL: counting not high after shift");
      $display("SELFTEST FAIL: counting state");
      $finish;
    end

    // Hold counting for a few cycles
    #30;
    if (done !== 0) begin
      $display("FAIL: done high before done_counting");
      $finish;
    end

    // Assert done_counting
    done_counting = 1;
    #10;
    done_counting = 0;

    if (done !== 1) begin
      $display("FAIL: done not high after done_counting");
      $display("SELFTEST FAIL: done state");
      $finish;
    end

    if (counting !== 0) begin
      $display("FAIL: counting still high in done state");
      $finish;
    end

    // Wait and acknowledge
    #20;
    ack = 1;
    #10;
    ack = 0;

    if (done !== 1) begin
      // Wait, after ack=1 on rising edge, done should go low on the next cycle
    end
    #2;
    if (done !== 0) begin
      $display("FAIL: done did not clear after ack");
      $finish;
    end

    $display("SELFTEST PASS");
    $finish;
  end

endmodule

module tb_TopModule;
  logic clk;
  logic reset;
  logic data;
  logic done_counting;
  logic ack;
  logic shift_ena;
  logic counting;
  logic done;

  TopModule dut (
    .clk(clk),
    .reset(reset),
    .data(data),
    .done_counting(done_counting),
    .ack(ack),
    .shift_ena(shift_ena),
    .counting(counting),
    .done(done)
  );

  // Clock generation: 10ns period, rising edge at 5, 15, 25...
  always #5 clk = ~clk;

  initial begin
    clk = 0;
    reset = 1;
    data = 0;
    done_counting = 0;
    ack = 0;

    @(posedge clk);
    @(posedge clk);
    reset = 0;
    @(posedge clk);

    // Send pattern 1101 synchronously with posedge clk
    data = 1; @(posedge clk); // bit 1
    data = 1; @(posedge clk); // bit 2
    data = 0; @(posedge clk); // bit 3
    data = 1; @(posedge clk); // bit 4 (pattern complete)

    // Now shift_ena should be high for 4 cycles
    // Cycle 1 of shift
    #1;
    if (!shift_ena) begin
      $display("FAIL: shift_ena not high on cycle 1");
      $display("SELFTEST FAIL: shift_ena count 1");
      $finish;
    end
    @(posedge clk);

    // Cycle 2 of shift
    #1;
    if (!shift_ena) begin
      $display("FAIL: shift_ena not high on cycle 2");
      $finish;
    end
    @(posedge clk);

    // Cycle 3 of shift
    #1;
    if (!shift_ena) begin
      $display("FAIL: shift_ena not high on cycle 3");
      $finish;
    end
    @(posedge clk);

    // Cycle 4 of shift
    #1;
    if (!shift_ena) begin
      $display("FAIL: shift_ena not high on cycle 4");
      $finish;
    end
    @(posedge clk);

    // Now should be in counting state
    #1;
    if (!counting) begin
      $display("FAIL: counting not high");
      $finish;
    end

    // Wait and signal done_counting
    done_counting = 1;
    @(posedge clk);
    done_counting = 0;

    #1;
    if (!done) begin
      $display("FAIL: done not high");
      $finish;
    end

    // Acknowledge
    ack = 1;
    @(posedge clk);
    ack = 0;

    #1;
    if (done) begin
      $display("FAIL: done still high after ack");
      $finish;
    end

    $display("SELFTEST PASS");
    $finish;
  end

endmodule

