module tb_TopModule;
  logic clk;
  logic reset;
  logic data;
  logic done_counting;
  logic ack;
  logic shift_ena;
  logic counting;
  logic done;

  TopModule dut (
    .clk(clk),
    .reset(reset),
    .data(data),
    .done_counting(done_counting),
    .ack(ack),
    .shift_ena(shift_ena),
    .counting(counting),
    .done(done)
  );

  always #5 clk = ~clk;

  task send_bit(input b);
    begin
      #1 data = b;
      @(posedge clk);
    end
  endtask

  initial begin
    clk = 0;
    reset = 1;
    data = 0;
    done_counting = 0;
    ack = 0;

    @(posedge clk);
    @(posedge clk);
    reset = 0;
    @(posedge clk);

    // Test 1: Send 1101
    send_bit(1);
    send_bit(1);
    send_bit(0);
    send_bit(1);

    // Verify shift_ena for 4 cycles
    // Cycle 1
    #1;
    if (!shift_ena) begin $display("SELFTEST FAIL: shift_ena cycle 1"); $finish; end
    @(posedge clk);

    // Cycle 2
    #1;
    if (!shift_ena) begin $display("SELFTEST FAIL: shift_ena cycle 2"); $finish; end
    @(posedge clk);

    // Cycle 3
    #1;
    if (!shift_ena) begin $display("SELFTEST FAIL: shift_ena cycle 3"); $finish; end
    @(posedge clk);

    // Cycle 4
    #1;
    if (!shift_ena) begin $display("SELFTEST FAIL: shift_ena cycle 4"); $finish; end
    @(posedge clk);

    // Verify transition to counting
    #1;
    if (!counting) begin $display("SELFTEST FAIL: counting not active"); $finish; end
    if (shift_ena) begin $display("SELFTEST FAIL: shift_ena still active"); $finish; end

    // Wait for done_counting
    #20;
    done_counting = 1;
    @(posedge clk);
    done_counting = 0;

    // Verify done is active
    #1;
    if (!done) begin $display("SELFTEST FAIL: done not active"); $finish; end
    if (counting) begin $display("SELFTEST FAIL: counting still active in done state"); $finish; end

    // Wait and acknowledge
    #20;
    ack = 1;
    @(posedge clk);
    ack = 0;

    // Verify returned to SEARCH state (done goes low)
    #1;
    if (done) begin $display("SELFTEST FAIL: done did not clear after ack"); $finish; end

    // Test 2: Synchronous reset test
    reset = 1;
    @(posedge clk);
    reset = 0;
    @(posedge clk);
    if (dut.state != 2'b00) begin $display("SELFTEST FAIL: reset did not return state to S_SEARCH"); $finish; end

    $display("SELFTEST PASS");
    $finish;
  end

endmodule

